  "ui.audit10": [
    "시급제 성인·고정 근로시간 기준 추정치예요. 월급 계약, 포괄임금, 탄력근로, 미성년자 등 별도 기준은 급여 담당자와 확인해 주세요. 추가보수·지급기록·세금·보험 공제는 이 합계에 포함하지 않아요.",
    "This is an estimate based on hourly pay for adults and fixed working hours. Please check with the payroll manager for separate standards such as monthly salary contract, comprehensive wage, flexible working hours, and minors. Additional compensation, payment records, taxes, and insurance deductions are not included in this total.",
    "Đây là ước tính dựa trên mức lương hàng giờ cho người lớn và giờ làm việc cố định. Vui lòng kiểm tra với người quản lý tiền lương để biết các tiêu chuẩn riêng biệt như hợp đồng lương hàng tháng, mức lương toàn diện, giờ làm việc linh hoạt và trẻ vị thành niên. Khoản bồi thường bổ sung, hồ sơ thanh toán, thuế và các khoản khấu trừ bảo hiểm không được bao gồm trong tổng số này.",
    "这是根据成年人的小时工资和固定工作时间进行的估算。请向薪资经理查询月薪合同、综合工资、弹性工作时间、未成年人等单独标准。额外补偿、付款记录、税款和保险扣除额不包含在此总额中。",
    "時給制大人・固定勤労時間基準推定値です。月給契約、包括賃金、弾力労働、未成年者など別途基準は給与担当者とご確認ください。追加保守・支給記録・税金・保険控除はこの合計に含まれません。",
    "นี่เป็นการประมาณการตามค่าจ้างรายชั่วโมงสำหรับผู้ใหญ่และชั่วโมงทำงานที่แน่นอน โปรดตรวจสอบกับผู้จัดการบัญชีเงินเดือนเพื่อดูมาตรฐานแยกต่างหาก เช่น สัญญาเงินเดือนรายเดือน ค่าจ้างที่ครอบคลุม ชั่วโมงการทำงานที่ยืดหยุ่น และผู้เยาว์ ค่าตอบแทนเพิ่มเติม บันทึกการชำระเงิน ภาษี และการหักประกันภัยจะไม่รวมอยู่ในยอดรวมนี้",
    "यो वयस्कहरूको लागि प्रति घण्टा तलब र निश्चित काम घण्टामा आधारित अनुमान हो। कृपया मासिक तलब सम्झौता, व्यापक ज्याला, लचिलो काम गर्ने घण्टा, र नाबालिगहरू जस्ता छुट्टै मापदण्डहरूको लागि पेरोल प्रबन्धकसँग जाँच गर्नुहोस्। थप क्षतिपूर्ति, भुक्तानी रेकर्ड, कर, र बीमा कटौती यस कुलमा समावेश गरिएको छैन।",
    "Ini adalah perkiraan berdasarkan upah per jam untuk orang dewasa dan jam kerja tetap. Silakan tanyakan kepada manajer penggajian untuk standar terpisah seperti kontrak gaji bulanan, upah komprehensif, jam kerja fleksibel, dan anak di bawah umur. Kompensasi tambahan, catatan pembayaran, pajak, dan potongan asuransi tidak termasuk dalam total ini.",
  ],
