  "ui.audit12": [
    "단시간 근로자의 주휴시간은 4주 소정근로시간 ÷ 같은 기간 통상근로자의 소정근로일수로 확인해 입력하세요. 일반 주 5일·40시간제는 8시간이에요.",
    "Please enter the weekly rest time for part-time workers as the 4-week regular working hours ÷ the number of regular working days during the same period. A typical 5-day/40-hour week is 8 hours.",
    "Vui lòng nhập thời gian nghỉ ngơi hàng tuần đối với người lao động bán thời gian là số giờ làm việc bình thường trong 4 tuần / số ngày làm việc bình thường trong cùng thời gian. Một tuần 5 ngày/40 giờ điển hình là 8 giờ.",
    "请输入兼职工人的每周休息时间，即 4 周正常工作时间 ÷ 同期正常工作日天数。典型的每周 5 天/40 小时工作时间为 8 小时。",
    "短時間労働者の週休時間は、4週間の所定労働時間÷同じ期間、通常労働者の所定労働日数で確認して入力してください。一般週5日・40時間制は8時間です。",
    "โปรดป้อนเวลาพักรายสัปดาห์สำหรับคนทำงานนอกเวลาเป็นชั่วโมงทำงานปกติ 4 สัปดาห์ ÷ จำนวนวันทำงานปกติในช่วงเวลาเดียวกัน โดยทั่วไปแล้ว สัปดาห์ที่มี 5 วัน/40 ชั่วโมงคือ 8 ชั่วโมง",
    "कृपया पार्ट-टाइम कामदारहरूको लागि साप्ताहिक विश्राम समय 4-हप्ताको नियमित काम घण्टाको रूपमा प्रविष्ट गर्नुहोस् ÷ सोही अवधिमा नियमित कामका दिनहरूको संख्या। एक सामान्य 5-दिन/40-घण्टा हप्ता 8 घण्टा हो।",
