  "ui.audit69": [
    "매일은 영업일마다, 매주·매월은 예정일에 들어가요. 휴무일이면 다음 영업일로 넘어가요.",
    "Every day counts as a business day, and every week and month counts as a due date. If it is a holiday, it moves on to the next business day.",
