    "Maintain business hours, crew, and existing records. If you don't have the part you need, you can directly designate a person in charge.",
    "Duy trì giờ làm việc, nhân viên và hồ sơ hiện có. Nếu bạn không có phần bạn cần, bạn có thể trực tiếp chỉ định một người phụ trách.",
    "维护营业时间、工作人员和现有记录。如果没有您需要的部分，可以直接指定负责人。",
