    "개인화·자체 작성 TAP과 Task·매뉴얼·운영 규칙을 백업해요. 공용 연결 TAP과 업무 수행·출퇴근·급여 기록은 제외해요. 사진·영상 파일은 백업에 포함하지 않아요. 다른 매장에서는 등록 사진을 다시 올려 주세요.",
    "Back up personalized/self-written TAPs, tasks, manuals, and operating rules. Public connection TAP and work performance, attendance, and salary records are excluded. Photo and video files are not included in the backup. For other stores, please re-upload the registration photo.",
    "Sao lưu các TAP, nhiệm vụ, hướng dẫn sử dụng và quy tắc vận hành được cá nhân hóa/tự viết. Kết nối công khai TAP và hồ sơ hiệu suất công việc, sự chuyên cần và tiền lương đều bị loại trừ. Các tập tin ảnh và video không được bao gồm trong bản sao lưu. Các cửa hàng khác vui lòng upload lại ảnh đăng ký.",
    "备份个性化/自行编写的 TAP、任务、手册和操作规则。不包括公共连接TAP和工作绩效、出勤和工资记录。照片和视频文件不包含在备份中。其他店铺请重新上传登记照片。",
    "個人化・自己作成TAPとTask・マニュアル・運営ルールをバックアップします。共用連結TAPと業務遂行・出退勤・給与記録は除きます。写真・映像ファイルはバックアップに含めません。他の店舗では登録写真をもう一度アップロードしてください。",
    "สำรองข้อมูล TAP ส่วนบุคคล/ที่เขียนเอง งาน คู่มือ และกฎการปฏิบัติงาน ไม่รวมการเชื่อมต่อสาธารณะ TAP และประสิทธิภาพการทำงาน การเข้าร่วม และบันทึกเงินเดือน ไฟล์ภาพถ่ายและวิดีโอไม่รวมอยู่ในการสำรองข้อมูล สำหรับร้านค้าอื่นๆ โปรดอัปโหลดภาพการลงทะเบียนอีกครั้ง",
    "निजीकृत/स्व-लिखित TAPs, कार्यहरू, म्यानुअलहरू, र सञ्चालन नियमहरू ब्याकअप गर्नुहोस्। सार्वजनिक जडान TAP र कार्य प्रदर्शन, उपस्थिति, र तलब रेकर्डहरू बहिष्कृत छन्। फोटो र भिडियो फाइलहरू ब्याकअपमा समावेश गरिएको छैन। अन्य स्टोरहरूको लागि, कृपया दर्ता फोटो पुन: अपलोड गर्नुहोस्।",
    "Cadangkan TAP, tugas, manual, dan aturan pengoperasian yang dipersonalisasi/ditulis sendiri. TAP koneksi publik dan catatan prestasi kerja, kehadiran, dan gaji tidak termasuk. File foto dan video tidak disertakan dalam cadangan. Untuk toko lain harap upload ulang foto registrasi.",
  ],
