    "Ông chủ luôn được phép. Các mục được bật chỉ có thể được sử dụng trong phạm vi quyền hạn của vị trí hiện có. Chỉ có ông chủ mới có thể nhìn thấy mức lương và tiền lương theo giờ.",
    "老板总是允许的。开启的项目只能在现有职位的权限范围内使用。只有老板才能看到工资和计时工资。",
    "社長はいつも許されます。オン項目も既存の役職の権限範囲内でのみ使用できます。給与・時給は社長のみ見ることができます。",
    "เจ้านายจะได้รับอนุญาตเสมอ รายการที่เปิดใช้งานสามารถใช้ได้ภายในขอบเขตอำนาจของตำแหน่งที่มีอยู่เท่านั้น มีเพียงเจ้านายเท่านั้นที่สามารถดูเงินเดือนและค่าจ้างรายชั่วโมงได้",
    "मालिक सधैं अनुमति छ। अन गरिएका वस्तुहरू अवस्थित स्थितिको अधिकारको दायरा भित्र मात्र प्रयोग गर्न सकिन्छ। केवल मालिकले तलब र घण्टाको ज्याला देख्न सक्छ।",
    "Bos selalu mengizinkan. Item yang diaktifkan hanya dapat digunakan dalam lingkup kewenangan posisi yang ada. Hanya bos yang dapat melihat gaji dan upah per jam.",
