  "ui.audit269": [
    "사용할 방식을 미리 선택해요. 현재는 직접 출퇴근 버튼으로 기록하며, 자동 감지는 기기 연동 후 사용할 수 있어요.",
    "Select the method you want to use in advance. Currently, it is recorded directly using the commute button, and automatic detection is available after linking with the device.",
    "Chọn trước phương pháp bạn muốn sử dụng. Hiện tại, nó được ghi trực tiếp bằng nút đi lại và khả năng tự động phát hiện sau khi liên kết với thiết bị.",
    "提前选择您要使用的方法。目前是直接使用上下班按键进行记录，与设备联动后可自动检测。",
    "使用する方法を事前に選択してください。現在は直接出退勤ボタンで記録し、自動検知は機器連動後に使用できます。",
    "เลือกวิธีการที่คุณต้องการใช้ล่วงหน้า ขณะนี้มีการบันทึกโดยตรงโดยใช้ปุ่มเดินทาง และการตรวจจับอัตโนมัติจะพร้อมใช้งานหลังจากเชื่อมโยงกับอุปกรณ์",
    "तपाईंले पहिले नै प्रयोग गर्न चाहनुभएको विधि चयन गर्नुहोस्। हाल, यो सीधा कम्युट बटन प्रयोग गरेर रेकर्ड गरिएको छ, र यन्त्रसँग लिङ्क गरेपछि स्वचालित पहिचान उपलब्ध छ।",
    "Pilih metode yang ingin Anda gunakan terlebih dahulu. Saat ini, rekaman tersebut langsung menggunakan tombol perjalanan, dan deteksi otomatis tersedia setelah terhubung dengan perangkat.",
  ],
  "ui.audit270": [
    "저장하면 선택·변경한 요일의 오늘 이후 근무표에 기간 제한 없이 적용해요. 기존 미세 조정·개별 배정·배정 삭제는 초기화돼요. 이후 날짜별로 별도 설정하면 해당 날짜에 우선 적용돼요. 출퇴근 이력과 승인·대기 중인 변경 신청은 유지돼요.",
    "If you save it, the selected/changed day will be applied to the work schedule after today without any period limit. Existing fine adjustments, individual assignments, and deletion of assignments are reset. If you set it separately for each date thereafter, it will be applied to that date first. Commute history and approved/pending change requests are maintained.",
    "Nếu bạn lưu lại, ngày đã chọn/thay đổi sẽ được áp dụng vào lịch làm việc sau ngày hôm nay mà không có bất kỳ giới hạn thời gian nào. Các điều chỉnh tốt hiện có, các bài tập riêng lẻ và việc xóa các bài tập đều được đặt lại. Nếu bạn đặt riêng cho từng ngày sau đó, nó sẽ được áp dụng cho ngày đó trước tiên. Lịch sử đi lại và các yêu cầu thay đổi đã được phê duyệt/đang chờ xử lý đều được duy trì.",
    "如果保存，所选/更改的日期将应用于今天之后的工作计划，没有任何期间限制。现有的微调、单独的分配和分配的删除都会被重置。如果您为此后的每个日期单独设置，它将首先应用于该日期。维护通勤历史记录和已批准/待处理的变更请求。",
    "保存すると選択・変更した曜日の今日以降勤務表に期間制限なく適用します。既存の微調整・個別割り当て・割り当て削除は初期化されます。以降、日付別に別に設定すると、その日付に優先適用されます。出退勤履歴と承認・待機中の変更申請は維持されます。",
    "หากคุณบันทึก วันที่เลือก/เปลี่ยนแปลงจะถูกนำไปใช้กับตารางการทำงานหลังจากวันนี้โดยไม่มีการจำกัดระยะเวลา การปรับแบบละเอียดที่มีอยู่ การมอบหมายงานแต่ละรายการ และการลบการมอบหมายงานจะถูกรีเซ็ต หากคุณตั้งค่าแยกกันสำหรับแต่ละวันที่หลังจากนั้น ระบบจะนำไปใช้กับวันนั้นก่อน ประวัติการเดินทางและคำขอเปลี่ยนแปลงที่ได้รับอนุมัติ/รอดำเนินการจะยังคงอยู่",
    "यदि तपाईंले यसलाई बचत गर्नुभयो भने, चयन गरिएको/परिवर्तन गरिएको दिन कुनै पनि अवधि सीमा बिना आज पछिको कार्य तालिकामा लागू हुनेछ। अवस्थित राम्रो समायोजनहरू, व्यक्तिगत असाइनमेन्टहरू, र असाइनमेन्टहरू मेटाउने रिसेट छन्। यदि तपाईंले त्यसपछि प्रत्येक मितिको लागि छुट्टै सेट गर्नुभयो भने, यो पहिले त्यो मितिमा लागू हुनेछ। कम्युट इतिहास र अनुमोदित/बाँकी परिवर्तन अनुरोधहरू राखिएका छन्।",
    "Jika disimpan, hari yang dipilih/diubah akan diterapkan ke jadwal kerja setelah hari ini tanpa batasan periode. Penyesuaian halus yang ada, tugas individu, dan penghapusan tugas akan diatur ulang. Jika Anda mengaturnya secara terpisah untuk setiap tanggal setelahnya, maka tanggal tersebut akan diterapkan terlebih dahulu. Riwayat perjalanan dan permintaan perubahan yang disetujui/menunggu dipertahankan.",
  ],
