  "ui.audit458": [
    "시간대마다 공동 업무를 만들어요. 실제 근무자를 담당자로 표시하며 같은 파트의 다른 크루도 지원 완료할 수 있어요.",
    "We create joint tasks in each time band. The actual worker is displayed as the person in charge, and other crews in the same part can also complete the application.",
    "Chúng tôi tạo ra các nhiệm vụ chung theo từng khung giờ. Người lao động thực tế được hiển thị là người phụ trách và các nhóm khác trong cùng bộ phận cũng có thể hoàn thành đơn đăng ký.",
    "我们在每个时间段创建联合任务。实际工人显示为负责人，同一工段的其他人员也可以完成申请。",
