    "เราสร้างงานร่วมกันในแต่ละช่วงเวลา ผู้ปฏิบัติงานจริงจะแสดงเป็นผู้รับผิดชอบ และทีมงานอื่นๆ ในส่วนเดียวกันก็สามารถกรอกใบสมัครได้เช่นกัน",
    "हामी प्रत्येक समयखण्डमा संयुक्त कार्यहरू सिर्जना गर्छौं। वास्तविक कार्यकर्तालाई प्रभारी व्यक्तिको रूपमा देखाइएको छ, र उही भागमा रहेका अन्य कर्मचारीहरूले पनि आवेदन पूरा गर्न सक्छन्।",
    "Kami membuat tugas bersama di setiap rentang waktu. Pekerja sebenarnya ditampilkan sebagai penanggung jawab, dan kru lain di bagian yang sama juga dapat melengkapi aplikasi.",
