  "ui.audit460": [
    "매장 영업일 경계부터 다음 경계까지 근무가 배정된 크루의 공용 업무예요. 휴무만 있는 크루는 제외해요.",
    "This is a common task for crew members assigned to work from one store business day to the next. Excluding crews who only have days off.",
    "Đây là nhiệm vụ chung của các thành viên trong nhóm được phân công làm việc từ ngày làm việc này sang ngày làm việc tiếp theo của cửa hàng. Ngoại trừ những đội chỉ có ngày nghỉ.",
