  "ui.audit555": [
    "내용을 수정하면 이 TAP은 개인화 항목으로 분리돼요. 이후 공용 업데이트 대신 백업으로 관리하고, 기존 업무 기록은 유지해요.",
    "If you modify the content, this TAP is separated into personalized items. Afterwards, we manage it as a backup instead of a public update, and maintain existing work records.",
    "Nếu bạn sửa đổi nội dung, TAP này sẽ được tách thành các mục được cá nhân hóa. Sau đó, chúng tôi quản lý nó dưới dạng bản sao lưu thay vì bản cập nhật công khai và duy trì các hồ sơ công việc hiện có.",
    "如果您修改内容，该 TAP 会被分成个性化项目。之后，我们将其作为备份而不是公共更新进行管理，并维护现有的工作记录。",
    "内容を修正すると、このTAPはパーソナライゼーション項目に分割されます。以後、パブリックアップデートの代わりにバックアップで管理し、既存の業務記録は維持します。",
    "หากคุณแก้ไขเนื้อหา TAP นี้จะถูกแยกออกเป็นรายการส่วนบุคคล หลังจากนั้น เราจะจัดการเป็นข้อมูลสำรองแทนการอัปเดตสาธารณะ และเก็บรักษาบันทึกงานที่มีอยู่",
    "यदि तपाईंले सामग्री परिमार्जन गर्नुभयो भने, यो TAP व्यक्तिगत वस्तुहरूमा विभाजित हुन्छ। पछि, हामी यसलाई सार्वजनिक अद्यावधिकको सट्टा ब्याकअपको रूपमा व्यवस्थापन गर्छौं, र अवस्थित कार्य रेकर्डहरू कायम राख्छौं।",
    "Jika Anda mengubah konten, TAP ini dipisahkan menjadi item yang dipersonalisasi. Setelah itu, kami mengelolanya sebagai cadangan, bukan sebagai pembaruan publik, dan memelihara catatan kerja yang ada.",
