  "ui.audit785": [
    "기존 미세 조정을 초기화하고 새 영업시간·인원 배치를 근무표에 반영했어요. 출퇴근·승인·대기 기록은 유지돼요.",
    "Existing fine adjustments were reset and the new business hours and staffing were reflected in the work schedule. Attendance, approval, and waiting records are maintained.",
    "Những điều chỉnh tốt hiện tại đã được thiết lập lại và giờ làm việc cũng như nhân sự mới được phản ánh trong lịch trình làm việc. Hồ sơ tham dự, phê duyệt và chờ đợi được duy trì.",
    "现有的微调被重置，新的营业时间和人员配置已反映在工作计划中。维护出勤、批准和等待记录。",
    "既存の微調整を初期化し、新しい営業時間・人員配置を勤務表に反映しました。出退勤・承認・待機記録は維持されます。",
    "การปรับค่าปรับที่มีอยู่ถูกรีเซ็ต และเวลาทำการใหม่และจำนวนพนักงานจะปรากฏในตารางการทำงาน บันทึกการเข้างาน การอนุมัติ และการรอจะถูกเก็บรักษาไว้",
