  "ui.audit793": [
    "구분선이나 시간을 끌어 30분 단위로 조정해요. 시간을 누르면 숫자로 선택할 수 있어요. 전체는 모든 영업일에 적용해요.",
    "Drag the dividing line or time to adjust it in 30-minute increments. You can select the time by number by pressing the time. The total applies to all business days.",
    "Kéo đường phân chia hoặc thời gian để điều chỉnh theo khoảng tăng 30 phút. Bạn có thể chọn thời gian theo số bằng cách nhấn thời gian. Tổng số áp dụng cho tất cả các ngày làm việc.",
    "拖动分割线或时间以 30 分钟为增量进行调整。您可以通过按时间按数字选择时间。总数适用于所有工作日。",
    "区切り線や時間をドラッグして30分単位で調整します。時間を押すと数字で選べます。全体はすべての営業日に適用されます。",
    "ลากเส้นแบ่งหรือเวลาเพื่อปรับทีละ 30 นาที คุณสามารถเลือกเวลาตามตัวเลขได้โดยการกดเวลา ยอดรวมมีผลกับทุกวันทำการ",
