  "ui.audit830": [
    "{p0} ~ {p1}\n기존 반복 근무의 세부 시간 조정은 다시 설정해야 해요. 승인된 OFF·대타·출퇴근·대기 신청과 별도 근무는 유지해요.",
    "{p0} ~ {p1}\nDetailed time adjustments for existing repetitive work must be re-established. Approved OFF, substitute work, commuting, and standby applications and separate work are maintained.",
    "{p0} ~ {p1}\nViệc điều chỉnh chi tiết thời gian cho công việc lặp đi lặp lại hiện tại phải được thiết lập lại. Các ứng dụng TẮT đã được phê duyệt, công việc thay thế, đi lại và dự phòng cũng như công việc riêng biệt được duy trì.",
    "{p0} ~ {p1}\n必须重新对现有重复性工作进行详细的时间调整。保留批准的休假、替代工作、通勤和待命申请以及单独的工作。",
    "{p0}~{p1} \n既存の繰り返し作業の詳細時間調整はリセットする必要があります。承認されたOFF・対打・出退勤・待機申請とは別に勤務は維持します。",
    "{p0} ~ {p1}\nการปรับเปลี่ยนเวลาโดยละเอียดสำหรับงานที่ทำซ้ำที่มีอยู่จะต้องถูกสร้างขึ้นใหม่ ได้รับการอนุมัติปิด งานทดแทน การเดินทาง และแอปพลิเคชันสแตนด์บายและงานแยกจะยังคงอยู่",
    "{p0} ~ {p1}\nअवस्थित दोहोरिने कामको लागि विस्तृत समय समायोजन पुन: स्थापित हुनुपर्छ। अनुमोदित बन्द, प्रतिस्थापन कार्य, कम्युटिङ, र स्ट्यान्डबाइ एप्लिकेसनहरू र छुट्टै काम राखिएको छ।",
    "{p0} ~ {p1} \nPenyesuaian waktu yang terperinci untuk pekerjaan berulang yang ada harus ditetapkan kembali. Disetujui MATI, pekerjaan pengganti, perjalanan pulang pergi, dan aplikasi siaga serta pekerjaan terpisah dipertahankan.",
  ],
  "ui.audit831": [
    "선택한 기간에 적용했어요. 근무표에서 세부 시간을 조정해 주세요.",
    "Applied for the selected period. Please adjust the detailed time in the work schedule.",
    "Áp dụng cho khoảng thời gian đã chọn. Vui lòng điều chỉnh thời gian chi tiết trong lịch làm việc.",
    "适用于所选期间。请调整工作安排中的具体时间。",
    "選択した期間に適用しました。勤務表で詳細時間を調整してください。",
    "ใช้สำหรับช่วงเวลาที่เลือก กรุณาปรับเวลาโดยละเอียดในตารางการทำงาน",
    "चयन गरिएको अवधिको लागि आवेदन। कृपया कार्य तालिकामा विस्तृत समय समायोजन गर्नुहोस्।",
    "Berlaku untuk periode yang dipilih. Silakan sesuaikan rincian waktu dalam jadwal kerja.",
