  "ui.audit836": [
    "15h는 주휴 조건을 확인하는 참고선이에요. 실제 주휴 여부는 4주 평균 소정근로시간·출근 등 조건을 확인해야 해요. 36h부터 주 40h 근접 표시를 해요. 실제 근로·급여 계산은 별도이며 매장 브레이크는 자동 차감하지 않아요.",
    "15h is a reference line to check weekly vacation conditions. To determine whether there are actual weekly holidays, you must check conditions such as average working hours over the four weeks and attendance at work. It displays from 36h to 40h per week. Actual work and salary calculations are separate, and store breaks are not automatically deducted.",
    "15h là đường tham chiếu để kiểm tra điều kiện nghỉ phép hàng tuần. Để xác định xem có thực sự có ngày nghỉ hàng tuần hay không, bạn phải kiểm tra các điều kiện như số giờ làm việc trung bình trong bốn tuần và sự tham gia tại nơi làm việc. Nó hiển thị từ 36h đến 40h mỗi tuần. Việc tính toán công việc thực tế và lương là riêng biệt và thời gian nghỉ tại cửa hàng không được tự động khấu trừ.",
    "15小时是检查每周休假情况的参考线。要确定是否有实际的每周假期，您必须检查四个星期的平均工作时间和工作出勤等条件。它显示每周 36 小时到 40 小时。实际工作和工资计算是分开的，商店休息时间不会自动扣除。",
    "15hは週休条件を確認する参考線です。実際の休休の可否は、4週間の平均所定勤務時間・出勤などの条件を確認する必要があります。 36hから週40h近接表示をします。実際の勤労・給与計算は別途で、店舗ブレーキは自動差し引かれません。",
    "15h เป็นเส้นอ้างอิงเพื่อตรวจสอบเงื่อนไขวันหยุดประจำสัปดาห์ หากต้องการทราบว่ามีวันหยุดประจำสัปดาห์จริงหรือไม่ คุณต้องตรวจสอบเงื่อนไข เช่น ชั่วโมงทำงานเฉลี่ยในช่วงสี่สัปดาห์ และการเข้าร่วมในที่ทำงาน โดยจะแสดงตั้งแต่ 36 ชั่วโมงถึง 40 ชั่วโมงต่อสัปดาห์ การคำนวณงานจริงและเงินเดือนจะแยกจากกัน และช่วงพักร้านค้าจะไม่ถูกหักออกโดยอัตโนมัติ",
    "15h साप्ताहिक छुट्टी अवस्थाहरू जाँच गर्न एक सन्दर्भ रेखा हो। वास्तविक साप्ताहिक बिदाहरू छन् कि छैनन् भनी निर्धारण गर्न, तपाईंले चार हप्तामा काम गर्ने औसत घण्टा र काममा उपस्थिति जस्ता सर्तहरू जाँच गर्नुपर्छ। यो प्रति हप्ता 36 घन्टा देखि 40 घन्टा सम्म प्रदर्शित हुन्छ। वास्तविक काम र तलब गणनाहरू अलग छन्, र स्टोर ब्रेकहरू स्वचालित रूपमा कटौती हुँदैनन्।",
    "15h adalah garis referensi untuk memeriksa kondisi liburan mingguan. Untuk menentukan apakah ada hari libur mingguan yang sebenarnya, Anda harus memeriksa kondisi seperti rata-rata jam kerja selama empat minggu dan kehadiran di tempat kerja. Ini ditampilkan dari 36 jam hingga 40 jam per minggu. Perhitungan pekerjaan dan gaji sebenarnya terpisah, dan istirahat di toko tidak dipotong secara otomatis.",
  ],
  "ui.audit837": [
    "기본 배정을 저장한 뒤 기간을 정해 근무표에 적용해 주세요. 앞 설정이 바뀌면 다시 적용해야 해요.",
    "After saving the basic assignment, set a period and apply it to the work schedule. If the previous settings change, they must be reapplied.",
    "Sau khi lưu bài tập cơ bản, hãy đặt khoảng thời gian và áp dụng nó vào lịch làm việc. Nếu cài đặt trước đó thay đổi, chúng phải được áp dụng lại.",
    "保存基本任务后，设置一个时间段并将其应用到工作计划中。如果先前的设置发生更改，则必须重新应用它们。",
    "基本割り当てを保存してから期間を定めて勤務表に適用してください。前の設定が変わったら、もう一度適用する必要があります。",
    "หลังจากบันทึกงานพื้นฐานแล้ว ให้กำหนดระยะเวลาและนำไปใช้กับตารางการทำงาน หากการตั้งค่าก่อนหน้านี้เปลี่ยนแปลง จะต้องนำมาใช้ใหม่",
    "आधारभूत असाइनमेन्ट बचत गरेपछि, अवधि सेट गर्नुहोस् र कार्य तालिकामा लागू गर्नुहोस्। यदि अघिल्लो सेटिङहरू परिवर्तन भएमा, तिनीहरू पुन: लागू गर्नुपर्छ।",
