  "ui.audit941": [
    "{p0}부터 앞으로 반복되는 업무에 적용돼요. 오늘 업무와 진행·완료 기록은 그대로 유지해요.",
    "It applies to future repetitive tasks starting from {p0}. I maintain today’s work and progress/completion records as is.",
    "Nó áp dụng cho các nhiệm vụ lặp đi lặp lại trong tương lai bắt đầu từ {p0}. Tôi duy trì hồ sơ công việc và tiến độ/hoàn thành của ngày hôm nay.",
    "它适用于从{p0}开始的未来重复性任务。我按原样保留今天的工作和进度/完成记录。",
    "{p0}から今後繰り返される業務に適用されます。今日の業務と進行・完了記録はそのまま維持します。",
    "โดยใช้กับงานที่เกิดซ้ำในอนาคตโดยเริ่มจาก {p0} ฉันรักษาบันทึกงานและความคืบหน้า/ความสำเร็จของวันนี้ไว้ดังที่เป็นอยู่",
    "यो {p0} बाट सुरु हुने भविष्यमा दोहोरिने कार्यहरूमा लागू हुन्छ। म आजको काम र प्रगति/समापन रेकर्डहरू यथावत राख्छु।",
    "Ini berlaku untuk tugas berulang di masa depan mulai dari {p0}. Saya menyimpan catatan pekerjaan dan kemajuan/penyelesaian hari ini sebagaimana adanya.",
  ],
  "ui.audit942": [
    "담당 변경은 오늘 아직 시작하지 않은 업무에도 적용돼요. 진행 중·완료 업무는 유지하고, 나머지 규칙은 다음 업무부터 적용해요.",
    "The change in responsibility also applies to tasks that have not yet started today. In progress and completed tasks are maintained, and the remaining rules apply from the next task.",
    "Sự thay đổi về trách nhiệm cũng áp dụng cho những nhiệm vụ chưa bắt đầu ngày hôm nay. Các nhiệm vụ đang tiến hành và đã hoàn thành sẽ được duy trì và các quy tắc còn lại sẽ được áp dụng từ nhiệm vụ tiếp theo.",
    "责任的变化也适用于今天尚未开始的任务。维护进行中和已完成的任务，并从下一个任务开始应用其余规则。",
    "担当変更は今日まだ始まっていない業務にも適用されます。進行中・完了業務は維持し、残りの規則は次の業務から適用します。",
    "การเปลี่ยนแปลงความรับผิดชอบยังใช้กับงานที่ยังไม่ได้เริ่มในวันนี้ด้วย งานที่อยู่ระหว่างดำเนินการและเสร็จสมบูรณ์จะคงอยู่ และกฎที่เหลือจะนำไปใช้จากงานถัดไป",
    "उत्तरदायित्वमा परिवर्तन आजदेखि सुरु नभएका कार्यहरूमा पनि लागू हुन्छ। प्रगतिमा र सम्पन्न कार्यहरू राखिएका छन्, र बाँकी नियमहरू अर्को कार्यबाट लागू हुनेछन्।",
