  "ui.audit1049": [
    "{p0} ~ {p1}\n{p2} · 기존 반복 근무 {p3}건 중 보호되지 않은 날짜 갱신\n\n승인된 OFF·대체 배정·출퇴근·대기 신청이 있는 날짜는 유지해요. 나머지 날짜의 반복 배정과 미세조정만 초기화해요. 별도 근무는 보존해요. 시간이 겹치면 전체 적용을 멈춰요.",
    "{p0} ~ {p1}\n{p2} · Update unprotected dates among existing recurring work {p3} cases\n\nWe maintain the dates with approved OFF, alternative assignment, commute, and standby requests. Only the repetitive assignment and fine-tuning of the remaining dates are reset. Separate work is preserved. If the times overlap, the entire application stops.",
    "{p0} ~ {p1}\n{p2} · Cập nhật ngày không được bảo vệ trong số các trường hợp {p3} công việc định kỳ hiện có\n\nChúng tôi duy trì các ngày với các yêu cầu TẮT, phân công thay thế, đi lại và dự phòng đã được phê duyệt. Chỉ các nhiệm vụ lặp đi lặp lại và tinh chỉnh các ngày còn lại mới được đặt lại. Công việc riêng biệt được bảo tồn. Nếu thời gian trùng nhau, toàn bộ ứng dụng sẽ dừng lại.",
    "{p0} ~ {p1}\n{p2} · 更新现有重复工作 {p3} 案例中不受保护的日期\n\n我们会根据批准的休假、替代分配、通勤和待命请求来维护日期。仅重置剩余日期的重复分配和微调。单独的工作被保留。如果时间重叠，整个应用程序就会停止。",
    "{p0}~{p1}\n{p2}・既存の繰り返し勤務{p3}件のうち、保護されていない日付の更新\n\n承認されたOFF・代替割当・出退勤・待機申請がある日は維持します。残りの日付の繰り返し割り当てと微調整のみを初期化します。別途勤務は保存します。時間が重なると全体の適用を停止します。",
    "{p0} ~ {p1}\n{p2} · อัปเดตวันที่ที่ไม่มีการป้องกันระหว่างกรณีการทำงานที่เกิดซ้ำของ {p3}\n\nเราคงวันที่ไว้โดยได้รับการอนุมัติเป็น OFF การมอบหมายทางเลือก การเดินทาง และคำขอสแตนด์บาย เฉพาะการกำหนดซ้ำและการปรับวันที่ที่เหลืออย่างละเอียดเท่านั้นที่จะถูกรีเซ็ต งานที่แยกจากกันจะถูกเก็บรักษาไว้ หากเวลาทับซ้อนกัน แอปพลิเคชันทั้งหมดจะหยุดลง",
    "{p0} ~ {p1}\n{p2} · अवस्थित पुनरावर्ती कार्य {p3} मामिलाहरू बीच असुरक्षित मितिहरू अद्यावधिक गर्नुहोस्\n\nहामी अनुमोदित बन्द, वैकल्पिक असाइनमेन्ट, कम्युट, र स्ट्यान्डबाइ अनुरोधहरूको साथ मितिहरू कायम राख्छौं। केवल दोहोरिने असाइनमेन्ट र बाँकी मितिहरूको फाइन-ट्यूनिङ रिसेट गरिन्छ। छुट्टै काम सुरक्षित छ। यदि समय ओभरल्याप हुन्छ भने, सम्पूर्ण अनुप्रयोग रोकिन्छ।",
    "{p0} ~ {p1} \n {p2} · Perbarui tanggal yang tidak dilindungi di antara kasus {p3} pekerjaan berulang yang ada\n\nKami mempertahankan tanggal dengan OFF yang disetujui, penugasan alternatif, perjalanan, dan permintaan siaga. Hanya penugasan berulang dan penyesuaian sisa tanggal yang direset. Pekerjaan terpisah telah dipertahankan. Jika waktunya tumpang tindih, seluruh aplikasi akan berhenti.",
  ],
