  "ui.audit1185": [
    "공급처별로 나눠 정리해요. 결제·문자·카카오 전송은 없는 체험이에요.",
    "Divide and organize by supplier. It is an experience without payment, text messaging, or Kakao messaging.",
    "Phân chia và tổ chức theo nhà cung cấp. Đó là trải nghiệm không cần thanh toán, nhắn tin văn bản hoặc nhắn tin Kakao.",
    "按供应商划分和组织。这是一种无需支付、短信或 Kakao 消息的体验。",
    "供給先別に分けて整理します。決済・文字・カカオ転送はない体験です。",
    "แบ่งและจัดระเบียบตามซัพพลายเออร์ เป็นประสบการณ์ที่ไม่ต้องชำระเงิน ส่งข้อความ หรือส่งข้อความ Kakao",
    "विभाजन र आपूर्तिकर्ता द्वारा संगठित। यो भुक्तानी, पाठ सन्देश, वा Kakao सन्देश बिना एक अनुभव हो।",
    "Bagi dan atur berdasarkan pemasok. Ini adalah pengalaman tanpa pembayaran, pesan teks, atau pesan Kakao.",
