  "ui.audit1319": [
    "연습 {p0}/6 · 함께 확인 {p1}/6\n시간은 안내용이에요. 이해가 안 되면 더 연습해도 괜찮아요.",
    "Practice {p0}/6 · Check together {p1}/6\nTimes are for guidance only. If you don't understand, it's okay to practice more.",
    "Thực hành {p0}/6 · Cùng kiểm tra {p1}/6\nThời gian chỉ mang tính hướng dẫn. Nếu chưa hiểu có thể luyện tập thêm.",
    "练习{p0}/6·一起检查{p1}/6\n时间仅供参考。如果不懂的话，多练习一下也是可以的。",
