    "ฝึก {p0}/6 · ตรวจสอบ {p1}/6 ด้วยกัน\nเวลามีไว้เพื่อเป็นแนวทางเท่านั้น ถ้าไม่เข้าใจก็ฝึกเพิ่มเติมได้",
    "{p0}/6 अभ्यास गर्नुहोस् · {p1}/6 सँगसँगै जाँच गर्नुहोस्\nसमय निर्देशनको लागि मात्र हो। यदि तपाईंले बुझ्नुभएको छैन भने, यो अधिक अभ्यास गर्न ठीक छ।",
    "Latihan {p0} /6 · Periksa bersama {p1} /6\nWaktu hanya untuk panduan. Jika belum paham, tidak apa-apa untuk lebih banyak berlatih.",
  ],
  "ui.audit1320": [
    "매장의 실제 절차를 버디와 확인해요. 이 체험은 매장의 필수 교육이나 자격 확인을 대신하지 않아요.",
    "Check the store’s actual procedures with Buddy. This experience does not replace required store training or qualification verification.",
    "Kiểm tra quy trình thực tế của cửa hàng với Buddy. Kinh nghiệm này không thay thế việc đào tạo bắt buộc của cửa hàng hoặc xác minh trình độ chuyên môn.",
