    "店舗の実際の手続きをバディと確認してください。この体験は店舗の必須教育や資格確認に代わるものではありません。",
    "ตรวจสอบขั้นตอนจริงของร้านค้ากับบัดดี้ ประสบการณ์นี้ไม่ได้แทนที่การฝึกอบรมร้านค้าที่จำเป็นหรือการตรวจสอบคุณสมบัติ",
    "बडीसँग स्टोरको वास्तविक प्रक्रियाहरू जाँच गर्नुहोस्। यो अनुभवले आवश्यक स्टोर प्रशिक्षण वा योग्यता प्रमाणीकरणलाई प्रतिस्थापन गर्दैन।",
    "Periksa prosedur sebenarnya toko dengan Buddy. Pengalaman ini tidak menggantikan pelatihan toko atau verifikasi kualifikasi yang diwajibkan.",
  ],
