  "ui.audit1340": [
    "현장에서 민지님을 먼저 불러 주세요. 급한 위험은 앱 답장을 기다리지 않고 바로 알려요.",
    "Please call Minji first at the scene. If there is an urgent danger, you will be notified right away without waiting for the app to respond.",
    "Vui lòng gọi cho Minji trước tại hiện trường. Nếu có mối nguy hiểm khẩn cấp, bạn sẽ được thông báo ngay lập tức mà không cần đợi ứng dụng phản hồi.",
    "请先致电现场的敏智。如果出现紧急危险，您将立即收到通知，无需等待应用程序响应。",
    "現場でミンジ様を先に呼んでください。急なリスクはアプリの返信を待たずにすぐにお知らせします。",
    "กรุณาโทรหามินจิก่อนในที่เกิดเหตุ หากมีเหตุฉุกเฉินจะแจ้งเตือนทันทีโดยไม่ต้องรอให้แอปตอบกลับ",
    "कृपया घटनास्थलमा पहिले मिन्जीलाई कल गर्नुहोस्। यदि त्यहाँ एक अत्यावश्यक खतरा छ भने, तपाईंलाई तुरुन्तै सूचित गरिनेछ एपको प्रतिक्रियाको लागि पर्खाइ बिना।",
    "Silakan hubungi Minji terlebih dahulu di tempat kejadian. Jika ada bahaya yang mendesak, Anda akan segera diberitahu tanpa menunggu aplikasi merespons.",
  ],
