    "Vui lòng gọi cho Minji trước tại hiện trường.\n\nYêu cầu trải nghiệm này chỉ được lưu trên thiết bị này. Tin nhắn thực tế không được gửi.",
    "请先致电现场的敏智。\n\n此体验的请求仅保存在此设备上。实际消息并未发送。",
    "現場でミンジ様を先に呼んでください。\n\nこの体験のリクエストはこの機器にのみ保存されます。実際のメッセージは送信されません。",
    "กรุณาโทรหามินจิก่อนในที่เกิดเหตุ\n\nคำขอประสบการณ์นี้จะถูกบันทึกไว้ในอุปกรณ์นี้เท่านั้น ข้อความจริงไม่ได้ถูกส่ง",
    "कृपया घटनास्थलमा पहिले मिन्जीलाई कल गर्नुहोस्।\n\nयो अनुभवका लागि अनुरोधहरू यस डिभाइसमा मात्र सुरक्षित हुन्छन्। वास्तविक सन्देश पठाइएको छैन।",
    "Silakan hubungi Minji terlebih dahulu di tempat kejadian.\n\nPermintaan pengalaman ini hanya disimpan di perangkat ini. Pesan sebenarnya tidak terkirim.",
  ],
