  "ui.audit1371": [
    "Flutter로 만든 tap2work 체험 버전이에요.\n\n가상 매장과 예시 인물이며 실제 직원 계정, 초대, 알림, 급여, 교육 영상은 아직 연결하지 않았어요. 진행 기록은 현재 기기에만 저장돼요.",
    "This is a trial version of tap2work made with Flutter.\n\nThis is a virtual store and example people, and we have not connected actual employee accounts, invitations, notifications, salaries, or training videos yet. Progress records are only saved on the current device.",
    "Đây là phiên bản dùng thử của tap2work được tạo bằng Flutter.\n\nĐây là một cửa hàng ảo và những người mẫu và chúng tôi chưa kết nối tài khoản nhân viên thực tế, lời mời, thông báo, tiền lương hoặc video đào tạo. Bản ghi tiến độ chỉ được lưu trên thiết bị hiện tại.",
    "这是用 Flutter 制作的 tap2work 的试用版。\n\n这是一个虚拟商店和示例人员，我们尚未连接实际的员工帐户、邀请、通知、工资或培训视频。进度记录仅保存在当前设备上。",
    "Flutterで作ったtap2work体験版です。\n\nバーチャルストアと例の人物であり、実際の従業員アカウント、招待状、通知、給与、教育ビデオはまだ接続していません。進行記録は現在の機器にのみ保存されます。",
    "นี่คือ tap2work เวอร์ชันทดลองที่สร้างด้วย Flutter\n\nนี่คือร้านค้าเสมือนจริงและบุคคลตัวอย่าง และเรายังไม่ได้เชื่อมโยงบัญชีพนักงาน คำเชิญ การแจ้งเตือน เงินเดือน หรือวิดีโอการฝึกอบรมของพนักงานจริง บันทึกความคืบหน้าจะถูกบันทึกไว้ในอุปกรณ์ปัจจุบันเท่านั้น",
    "यो Flutter संग बनाइएको tap2work को एक परीक्षण संस्करण हो।\n\nयो भर्चुअल स्टोर र उदाहरण मानिसहरू हो, र हामीले वास्तविक कर्मचारी खाताहरू, निमन्त्रणाहरू, सूचनाहरू, तलबहरू, वा प्रशिक्षण भिडियोहरू अझै जोडेका छैनौं। प्रगति रेकर्डहरू हालको यन्त्रमा मात्र सुरक्षित हुन्छन्।",
    "Ini adalah versi uji coba tap2work yang dibuat dengan Flutter.\n\nIni adalah toko virtual dan orang-orang contoh, dan kami belum menghubungkan akun karyawan sebenarnya, undangan, pemberitahuan, gaji, atau video pelatihan. Catatan kemajuan hanya disimpan di perangkat saat ini.",
  ],
